// Lookup: code point -> glyph index (-1 if not found)
static inline int kata_index(uint16_t code) {
  // Binary search on kata_codes (trend: sorted)
  int lo = 0, hi = KATA_N - 1;
  while (lo <= hi) {
    int mid = (lo + hi) >> 1;
    if (kata_codes[mid] == code) return mid;
    if (kata_codes[mid] < code) lo = mid + 1;
    else hi = mid - 1;
  }
  return -1;
}
